import sites from '../../data/spawn-sites.json' with {type:'json'};
import {MAP,INITIAL_TERRITORY_GROUPING} from './map.ts';
import {TERRAIN_REVISION} from './terrain-navigation.ts';
import {KINDS,LEADERS,MAP_ID} from './content.ts';
import type {GameState,PlayerSetup} from './types.ts';
// Generated by scripts/build-spawn-sites.mjs from legal bidirectional land links.
// Maximum matching reserves two complete, equal-budget groups per faction.
// This is the available map resource, not a configured player/AI seat ceiling.
if(sites.mapId!==MAP_ID||sites.terrainRevision!==TERRAIN_REVISION)throw new Error('incompatibleMap');
const allocatedGroups=new Set<string>();
for(const pair of sites.pairs){
 if(pair.length!==2)throw new Error('noSpawnRegions');
 for(const id of pair){const group=INITIAL_TERRITORY_GROUPING.atomToGroup[MAP[id]?.code];if(!group||allocatedGroups.has(group))throw new Error('noSpawnRegions');allocatedGroups.add(group);}
}
export function getSpawnCapacity():number{return sites.pairs.length;}
/** Server/local-session-owned AI seats. A lobby client can request only a count. */
export function makeAISetups(count:number,seed=0):PlayerSetup[]{
 if(!Number.isSafeInteger(count)||count<0||count>=getSpawnCapacity())throw new Error('invalidAI');
 return Array.from({length:count},(_,i)=>({name:`AI ${i+1}`,leader:LEADERS[i%LEADERS.length],loadout:[KINDS[((seed>>>0)+i+1)%KINDS.length]],ai:true}));
}
function hash(seed:number,id:number):number{let x=(seed^Math.imul(id+1,0x9e3779b9))>>>0;x=Math.imul(x^(x>>>16),0x85ebca6b);x=Math.imul(x^(x>>>13),0xc2b2ae35);return(x^(x>>>16))>>>0;}
const cache=new Map<number,[number,number][]>();
/** Seeded first site followed by farthest-point allocation. The complete pool is
 * already disjoint, so every advertised count works for every seed. At capacity
 * expansion may mean attacking a neighbor, but no start loses its land exits. */
export function chooseSpawnPairs(seed:number,count:number,_state?:GameState):[number,number][]{
 if(!Number.isInteger(seed)||seed<0||seed>0xffffffff||!Number.isSafeInteger(count)||count<2||count>getSpawnCapacity())throw new Error('invalidSetup');
 let order=cache.get(seed);
 if(!order){
  const remaining=sites.pairs.map((pair,index)=>({pair:pair as [number,number],index,distance:Infinity}));
  order=[];
  while(remaining.length){
   let best=0;
   for(let i=1;i<remaining.length;i++)if(remaining[i].distance>remaining[best].distance||(remaining[i].distance===remaining[best].distance&&(hash(seed,remaining[i].index)<hash(seed,remaining[best].index))))best=i;
   const [selected]=remaining.splice(best,1);order.push(selected.pair);
   for(const candidate of remaining)for(const a of candidate.pair)for(const b of selected.pair){const pa=MAP[a].center,pb=MAP[b].center;candidate.distance=Math.min(candidate.distance,(pa.x-pb.x)**2+(pa.z-pb.z)**2);}
  }
  if(cache.size>=32)cache.delete(cache.keys().next().value!);cache.set(seed,order);
 }
 return order.slice(0,count).map(pair=>[...pair]);
}
